use anyhow::{Result, bail};
use msvc6_base::digest::sha256_hex;

pub const ATTACH: &str = "ATTACH.md";
pub const MANIFEST: &str = "MANIFEST.tsv";
pub const DIR70: &str = "7.0";

pub const INTRO: &str = "# Attaching a debug record to your own copy\n\nGenerated by `msvc6t pdb release` for the PDBs beside this file. Each recipe is headed by the file it\nneeds; where an image has more than one accepted file, use the recipe whose md5 is your copy's.\n\n";

#[derive(Debug, Clone, PartialEq, Eq)]
pub struct Rev {
    pub name: String,
    pub commit: String,
}

pub fn parse_rev(s: &str) -> Result<Rev> {
    let Some((name, commit)) = s.split_once('=') else {
        bail!("`{s}` is not NAME=COMMIT");
    };
    let good = |c: char| c.is_ascii_alphanumeric() || matches!(c, '_' | '-' | '.');
    if name.is_empty() || !name.chars().all(good) {
        bail!("`{name}` is not a column name (letters, digits, `_`, `-`, `.`)");
    }
    if commit.is_empty() || !commit.chars().all(|c| c.is_ascii_hexdigit()) {
        bail!("`{commit}` is not a commit (hexadecimal)");
    }
    Ok(Rev {
        name: name.to_string(),
        commit: commit.to_string(),
    })
}

pub const COLUMNS: [&str; 3] = ["file", "bytes", "sha256"];

pub fn check_revs(revs: &[Rev]) -> Result<()> {
    for (i, r) in revs.iter().enumerate() {
        if revs.iter().take(i).any(|o| o.name == r.name) {
            bail!("the revision column `{}` is named twice", r.name);
        }
        if COLUMNS.contains(&r.name.as_str()) {
            bail!("`{}` is a manifest column of its own", r.name);
        }
    }
    Ok(())
}

pub fn manifest(files: &[(String, &[u8])], revs: &[Rev]) -> Result<String> {
    check_revs(revs)?;
    let mut out = COLUMNS.join("\t");
    for r in revs {
        out.push('\t');
        out.push_str(&r.name);
    }
    out.push('\n');
    for (i, (name, bytes)) in files.iter().enumerate() {
        if name.contains(['\t', '\n']) {
            bail!("the file name `{name}` holds a tab or a newline");
        }
        if files.iter().take(i).any(|(o, _)| o == name) {
            bail!("the file `{name}` is listed twice");
        }
        out.push_str(&format!("{name}\t{}\t{}", bytes.len(), sha256_hex(bytes)));
        for r in revs {
            out.push('\t');
            out.push_str(&r.commit);
        }
        out.push('\n');
    }
    Ok(out)
}

#[must_use]
pub fn attach_doc(intro: &str, recipes: &[String]) -> String {
    let mut out =
        String::with_capacity(intro.len() + recipes.iter().map(String::len).sum::<usize>());
    out.push_str(intro);
    for r in recipes {
        out.push_str(r);
    }
    out
}

#[cfg(test)]
#[allow(clippy::unwrap_used, clippy::indexing_slicing)]
mod tests {
    use super::*;

    #[test]
    fn a_manifest_row_is_a_files_size_hash_and_the_named_revisions() {
        let revs = vec![
            parse_rev("product=abc123").unwrap(),
            parse_rev("tooling=def4").unwrap(),
        ];
        let m = manifest(&[("a.pdb".into(), b"x"), ("7.0/a.pdb".into(), b"")], &revs).unwrap();
        let lines: Vec<&str> = m.lines().collect();
        assert_eq!(lines[0], "file\tbytes\tsha256\tproduct\ttooling");
        assert_eq!(
            lines[1],
            "a.pdb\t1\t2d711642b726b04401627ca9fbac32f5c8530fb1903cc4db02258717921a4881\tabc123\tdef4"
        );
        assert!(lines[2].starts_with("7.0/a.pdb\t0\te3b0c442"));
        assert!(m.ends_with('\n'));
        assert_eq!(manifest(&[], &[]).unwrap(), "file\tbytes\tsha256\n");
    }

    #[test]
    fn a_bad_revision_or_a_repeated_name_is_refused() {
        for bad in ["product", "=abc", "pro duct=abc", "product=xyz", "product="] {
            assert!(parse_rev(bad).is_err(), "{bad}");
        }
        let r = parse_rev("p=1").unwrap();
        assert!(check_revs(&[r.clone(), r.clone()]).is_err());
        assert!(manifest(&[], &[r.clone(), r]).is_err());
        for own in COLUMNS {
            assert!(check_revs(&[parse_rev(&format!("{own}=1")).unwrap()]).is_err());
        }
        assert!(manifest(&[], &[parse_rev("bytes=1").unwrap()]).is_err());
        assert!(check_revs(&[parse_rev("product=1").unwrap()]).is_ok());
        assert!(manifest(&[("a".into(), b""), ("a".into(), b"")], &[]).is_err());
        assert!(manifest(&[("a\tb".into(), b"")], &[]).is_err());
    }

    #[test]
    fn the_document_is_the_intro_then_each_recipe_in_order() {
        let d = attach_doc(INTRO, &["### one\n\n".into(), "### two\n\n".into()]);
        assert!(d.starts_with("# Attaching"));
        assert!(d.ends_with("### one\n\n### two\n\n"));
    }
}
